import sys
sys.setrecursionlimit(300000)

def main():
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    if n == 1:
        print(0)
        return

    idx = 1
    adj = [[] for _ in range(n + 1)]
    edges = []

    for i in range(n - 1):
        u = int(data[idx])
        v = int(data[idx + 1])
        idx += 2
        edges.append((u, v))
        adj[u].append((v, i + 1))
        adj[v].append((u, i + 1))

    parent = [0] * (n + 1)
    order = []
    stack = [1]
    visited = [False] * (n + 1)
    visited[1] = True

    while stack:
        u = stack.pop()
        order.append(u)
        for v, eid in adj[u]:
            if not visited[v]:
                visited[v] = True
                parent[v] = u
                stack.append(v)

    days = []
    current_day_roads = []
    max_depth = 0
    depth_map = {1: 0}

    for u in reversed(order):
        d = depth_map[u]
        if d % 2 == 0:
            if current_day_roads:
                days.append(current_day_roads)
                current_day_roads = []
            current_day_roads.append(u)
        else:
            if not current_day_roads:
                current_day_roads = []
            current_day_roads.append((u, d))

    if current_day_roads:
        days.append(current_day_roads)

    result_days = []

    for i, group in enumerate(days):
        if not group:
            continue
        road_list = []
        for item in group:
            if isinstance(item, tuple):
                u, d = item
                p = parent[u]
                for v, eid in adj[u]:
                    if v == p:
                        road_list.append(eid)
                        break
            else:
                u = item
                p = parent[u]
                for v, eid adj[u]:
                    if v == p:
                        road_list.append
                        break
        result_days.append(road_list)

    print(len(result_days))
    for rd in result_days:
        print(len(rd), *rd)

if __name__ == "__main__":
    main()
